import * as THREE from 'three';
import {OrbitControls} from '/vendor/floorplan/OrbitControls.js';
import {wallPieces} from './floorplan-model-core.mjs';
export function createViewer(container){const scene=new THREE.Scene();scene.background=new THREE.Color('#eff4ef');const camera=new THREE.PerspectiveCamera(38,1,.05,500),renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.95;renderer.domElement.setAttribute('aria-label','Drehbares 3D-Modell. Mit Maus oder Finger drehen; mit Mausrad oder zwei Fingern zoomen.');renderer.domElement.setAttribute('tabindex','0');container.replaceChildren(renderer.domElement);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.maxPolarAngle=Math.PI/2-.02;controls.minDistance=2;controls.maxDistance=120;controls.autoRotateSpeed=.7;const ambient=new THREE.HemisphereLight('#ffffff','#9aa998',1.15);scene.add(ambient);const sun=new THREE.DirectionalLight('#fff5e6',2.2);sun.position.set(-8,18,12);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-40,right:40,top:40,bottom:-40,near:.5,far:100});sun.shadow.camera.updateProjectionMatrix();sun.shadow.bias=-.0003;scene.add(sun);let root=null,current=null,cut=1.2,showFurniture=true;
const woodCanvas=document.createElement('canvas');woodCanvas.width=woodCanvas.height=512;const wc=woodCanvas.getContext('2d');wc.fillStyle='#c7a77e';wc.fillRect(0,0,512,512);for(let i=0;i<12;i++){const y=i*43;wc.fillStyle=i%3===0?'#c1a17b':i%3===1?'#d1b28b':'#c9aa82';wc.fillRect(0,y,512,42);wc.strokeStyle='#b5957045';wc.lineWidth=1;wc.beginPath();wc.moveTo(0,y);wc.lineTo(512,y);wc.stroke();for(let j=0;j<8;j++){const offset=4+j*4.5;wc.strokeStyle=j%2?'#765b3c12':'#fff9e31a';wc.beginPath();wc.moveTo(0,y+offset);wc.bezierCurveTo(130,y+offset+3,360,y+offset-2,512,y+offset);wc.stroke()}}const woodTex=new THREE.CanvasTexture(woodCanvas);woodTex.colorSpace=THREE.SRGBColorSpace;woodTex.wrapS=woodTex.wrapT=THREE.RepeatWrapping;woodTex.repeat.set(.16,.16);
const material=(color,extra={})=>new THREE.MeshStandardMaterial({color,roughness:.8,...extra});function box(parent,w,h,d,x,y,z,color){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),typeof color==='object'?color:material(color));mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);return mesh}
function furniture(f){const g=new THREE.Group(),w=f.width,d=f.depth,h=f.height;g.position.set(f.x*current.width,0,f.z*current.depth);g.rotation.y=-f.rotation*Math.PI/180;const wood='#c2a67f',linen='#ece7d8',green='#779487';if(f.type==='bed'){box(g,w,.25,d,0,.15,0,wood);box(g,w*.97,.22,d*.96,0,.38,0,linen);box(g,w*.95,.07,d*.52,0,.53,d*.12,green);box(g,w*.75,.13,d*.2,0,.55,-d*.32,'#fffaf0');box(g,w,.85,.08,0,.43,-d/2,wood)}else if(f.type==='sofa'){box(g,w,.32,d,0,.3,0,linen);box(g,w,.65,.18,0,.53,-d/2,linen);box(g,.16,.5,d,-w/2+.08,.45,0,linen);box(g,.16,.5,d,w/2-.08,.45,0,linen);for(let x=-.25;x<=.25;x+=.5)box(g,w*.25,.1,d*.5,x*w,.52,0,'#e4dfce')}else if(f.type==='table'||f.type==='chair'){box(g,w,.08,d,0,h-.04,0,wood);for(const x of [-1,1])for(const z of [-1,1])box(g,.045,h-.08,.045,x*w*.38,(h-.08)/2,z*d*.38,wood);if(f.type==='chair')box(g,w,.4,.05,0,h+.2,-d*.45,green)}else if(f.type==='wardrobe'||f.type==='cabinet'){box(g,w,h,d,0,h/2,0,f.type==='wardrobe'?wood:'#e9ece2');box(g,.025,h*.23,.025,0,h*.6,d/2+.02,'#8e948d')}else if(f.type==='toilet'){box(g,w*.75,.42,d*.75,0,.23,0,'#fbfcf9');box(g,w*.8,.7,d*.2,0,.38,-d*.4,'#fff')}else if(f.type==='bath'||f.type==='shower'){box(g,w,.2,d,0,.1,0,'#f9faf7');if(f.type==='bath'){box(g,.1,.5,d,-w/2,.25,0,'#fff');box(g,.1,.5,d,w/2,.25,0,'#fff');box(g,w,.5,.1,0,.25,d/2,'#fff');box(g,w,.5,.1,0,.25,-d/2,'#fff')}else box(g,.025,1.8,d,w/2,.9,0,material('#dbe9eb',{transparent:true,opacity:.25,roughness:.2}))}else{box(g,w,h*.8,d,0,h*.4,0,'#d1b58e');box(g,w,.12,d,0,h*.85,0,'#fff')}return g}
function dispose(){if(!root)return;root.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose()}});scene.remove(root)}
function build(model,{reset=false}={}){current=model;dispose();root=new THREE.Group();root.position.set(-model.width/2,0,-model.depth/2);scene.add(root);for(const room of model.rooms){const shape=new THREE.Shape();room.points.forEach((p,i)=>i?shape.lineTo(p.x*model.width,-p.z*model.depth):shape.moveTo(p.x*model.width,-p.z*model.depth));shape.closePath();const mesh=new THREE.Mesh(new THREE.ShapeGeometry(shape),material(room.floor==='wood'?'#ceb48c':room.floor==='tile'?'#c8d0c9':'#b7b7a5',{side:THREE.DoubleSide,...(room.floor==='wood'?{map:woodTex}:{})}));mesh.rotation.x=-Math.PI/2;mesh.position.y=.025;mesh.receiveShadow=true;root.add(mesh)}
for(const wall of model.walls){const dx=(wall.x2-wall.x1)*model.width,dz=(wall.z2-wall.z1)*model.depth,length=Math.hypot(dx,dz),angle=-Math.atan2(dz,dx);for(const p of wallPieces(wall,model.height)){const top=Math.min(p.top,cut),bottom=Math.min(p.bottom,cut);if(top<=bottom)continue;const middle=(p.start+p.end)/2;const mesh=box(root,length*(p.end-p.start),top-bottom,.13,wall.x1*model.width+dx*middle,(top+bottom)/2,wall.z1*model.depth+dz*middle,'#fffdf6');mesh.rotation.y=angle}for(const o of wall.openings.filter(o=>o.kind==='window')){const bottom=.9,top=Math.min(2.15,cut);if(top>bottom){const mid=(o.start+o.end)/2;const mesh=box(root,length*(o.end-o.start),top-bottom,.025,wall.x1*model.width+dx*mid,(top+bottom)/2,wall.z1*model.depth+dz*mid,material('#a8c8d0',{transparent:true,opacity:.28,roughness:.2}));mesh.rotation.y=angle}}}
if(showFurniture)for(const f of model.furniture)root.add(furniture(f));const ground=new THREE.Mesh(new THREE.PlaneGeometry(model.width*3,model.depth*3),material('#eff4ef'));ground.rotation.x=-Math.PI/2;ground.position.set(model.width/2,-.06,model.depth/2);ground.receiveShadow=true;root.add(ground);if(reset)resetCamera();render()}
function resetCamera(){if(!current)return;const size=Math.max(current.width,current.depth);camera.position.set(size*.9,size*1.1,size*1.15);controls.target.set(0,.25,0);controls.update()}
function render(){renderer.render(scene,camera)}const observer=new ResizeObserver(()=>{const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();render()});observer.observe(container);const clock=new THREE.Clock();renderer.setAnimationLoop(()=>{if(document.hidden)return;controls.update(Math.min(clock.getDelta(),.1));render()});return {build,reset:resetCamera,setCut(value){cut=value;if(current)build(current)},setFurniture(value){showFurniture=value;if(current)build(current)},rotate(value){controls.autoRotate=value},top(){if(!current)return;const size=Math.max(current.width,current.depth);camera.position.set(0,size*1.8,.01);controls.target.set(0,0,0);controls.update()},snapshot:()=>new Promise(resolve=>{render();renderer.domElement.toBlob(resolve,'image/png')}),destroy(){observer.disconnect();renderer.setAnimationLoop(null);controls.dispose();dispose();woodTex.dispose();renderer.dispose()}}}
